// Same effect as DISALLOW_FILE_EDIT, without editing wp-config.php.
add_filter( 'map_meta_cap', 'perfectpixel_disable_file_editor', 20, 2 );

function perfectpixel_disable_file_editor( $caps, $cap ) {
	if ( in_array( $cap, array( 'edit_plugins', 'edit_themes', 'edit_files' ), true ) ) {
		$caps[] = 'do_not_allow';
	}
	return $caps;
}
